import{_ as o,h as t,i as e,c,v as r,p as i,x as d,m as p,e as n,S as h}from"./chunks/framework.Dvtg8yj2.js";const B=JSON.parse('{"title":"CUDA Graph 捕获推理","description":"","frontmatter":{"title":"CUDA Graph 捕获推理","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cuda-graph-infer.md","filePath":"llm/cuda-graph-infer.md","lastUpdated":1788454257000}'),s={name:"llm/cuda-graph-infer.md"};function u(E,a,m,A,C,P){const l=t("Mermaid");return e(),c("div",null,[a[1]||(a[1]=r('<h1 id="cuda-graph-捕获推理" tabindex="-1">CUDA Graph 捕获推理 <a class="header-anchor" href="#cuda-graph-捕获推理" aria-label="Permalink to &quot;CUDA Graph 捕获推理&quot;">​</a></h1><div class="epigraph"><p>推理步若拓扑稳定，就把这一步录成图再重放：省掉的是逐步 `cudaLaunchKernel` 的 CPU 往返。形状一变，图要么更新参数，要么作废重建。</p><footer>—— NVIDIA CUDA C++ Programming Guide, CUDA Graphs；推理引擎中的 graph capture 实践</footer></div><p>通用 <a href="/llm/cuda-graph">CUDA Graph</a> 写的是捕获规则本身。推理把它用到一个很窄、却很苛刻的场景：decode 一步或一小段 prefill，kernel 短、数量多，CPU 提交与 GPU 执行咬在同一条关键路径上。vLLM、TensorRT-LLM、SGLang 一类引擎都把「固定 batch 桶上的 CUDA Graph」做成可选加速，而不是默认对任意动态批处理生效。本篇只写捕获如何为推理服务、分桶与更新、以及和连续批处理的摩擦。机制细节仍以 CUDA 文档为准，不把某一引擎的加速比写成通用 SLA。</p><p>与 <a href="/llm/continuous-batching">连续批处理</a> 的关系：Graph 要求这一步的网格与依赖可预知；连续批处理要求每步进出序列。二者能共存，靠的是 padding 与分桶，不是靠 Graph 学会动态拓扑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Decode 一步通常是「所有层的 RMSNorm → GEMM → 注意力 → 残差」的固定链条，层数不变，变的是 batch、当前序列长度、KV 页表指针。没有图时，每层每个核一次启动；核本身若只有几十微秒，启动税成为墙钟一阶项。有图时，一次 <code>cudaGraphLaunch</code> 提交整步。问题立刻变成：哪些量允许在重放时变化。CUDA 的合同是：拓扑（节点与边）在实例化时固定；部分节点参数可以 <code>cudaGraphExecUpdate</code> / <code>SetParams</code>；指针长度、grid 若超出更新允许的范围，更新失败，必须重新捕获。</p><p>推理还有捕获期禁止项：默认流、隐式同步、<code>.item()</code>、在捕获中 <code>cudaMalloc</code>。Python 框架的缓存分配器、日志里读标量 loss、以及按真实 batch 分配 KV 页，都是服务进程里最常见的捕获失败源。warmup 必须在捕获之外把缓冲吃满。</p><h3 id="为何-prefill-往往不上整图" tabindex="-1">为何 prefill 往往不上整图 <a class="header-anchor" href="#为何-prefill-往往不上整图" aria-label="Permalink to &quot;为何 prefill 往往不上整图&quot;">​</a></h3><p>Prefill 的核更胖，GEMM 以毫秒计，启动税占比低；序列长度几乎每请求不同，拓扑或 grid 变化频繁，重建图的代价容易超过收益。工程上常见的是：decode 分桶上图，prefill 逐步启动或只把层内静态段做成小图。把「启用 CUDA Graph」理解成整条请求生命周期都在图里，会在变长 prefill 上得到负优化。</p><p><span class="marginnote">捕获时 GPU 通常不执行工作（相对默认捕获语义），因此不能根据这一步的真实 token 数在捕获里做 CPU 分支。token 数必须来自预先选好的桶，或核内自己读一个固定地址上的标量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务进程侧的标准流程是：</p><ol><li>按 max batch、max 捕获长度做 warmup，分配权重、KV 池、workspace（含 <a href="/llm/cublas-cudnn">cuDNN</a> 计划缓冲）。</li><li>对每个接受的 <code>(batch_bucket, length_bucket)</code> 在非默认流上捕获一步 decode（或一层的静态子图）。</li><li>实例化，缓存 <code>cudaGraphExec_t</code>。</li><li>真实请求 padding 到桶；KV 与激活写在捕获时用的那批基址上，或走文档允许的参数更新把指针换到当前页表。</li><li><code>cudaGraphLaunch</code>；步末按真实长度做后处理（取样、写回 KV），后处理往往在图外，以免把采样控制流录进去。</li></ol>',13)),(e(),i(h,null,{default:d(()=>[n(l,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22Warmup%20%E5%88%86%E9%85%8D%20%2F%20%E9%80%89%E8%AE%A1%E5%88%92%22%5D%20--%3E%20B%5B%22%E9%80%89%20batch%C3%97%E9%95%BF%E5%BA%A6%E6%A1%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%9D%9E%E9%BB%98%E8%AE%A4%E6%B5%81%E6%8D%95%E8%8E%B7%E4%B8%80%E6%AD%A5%20decode%22%5D%0A%20%20C%20--%3E%20I%5B%22instantiate%20%E5%B9%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20I%20--%3E%20P%5B%22%E8%AF%B7%E6%B1%82%20padding%20%E5%88%B0%E6%A1%B6%22%5D%0A%20%20P%20--%3E%20L%5B%22graph%20launch%22%5D%0A%20%20L%20--%3E%20S%7B%22%E6%8C%87%E9%92%88%E6%88%96%E6%8B%93%E6%89%91%3F%22%7D%0A%20%20S%20--%3E%7C%22%E4%BB%85%E6%8C%87%E9%92%88%EF%BC%8Cupdate%20%E6%88%90%E5%8A%9F%22%7C%20L%0A%20%20S%20--%3E%7C%22%E6%8B%93%E6%89%91%E6%88%96%E6%9B%B4%E6%96%B0%E5%A4%B1%E8%B4%A5%22%7C%20C%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="分桶、padding-与显存" tabindex="-1">分桶、padding 与显存 <a class="header-anchor" href="#分桶、padding-与显存" aria-label="Permalink to &quot;分桶、padding 与显存&quot;">​</a></h3><p>桶太多，可执行图和 padding 激活一起涨显存；桶太少，小请求被 pad 到大 GEMM，算力浪费，decode 的 <a href="/llm/decode-memory-wall">显存墙</a> 更疼。实践是对数或阶梯分 batch（1, 2, 4, 8, …）以及少数长度截断点。Padding 的 token 必须在核里用掩码排除，否则污染 KV 与 logits。图并不知道哪些是 pad，掩码是算子合同，不是 Graph API。</p><p>页式 KV 的页表每步变。两种做法：把页表放进固定缓冲，核每次间接加载——图内指针不变；或每步 <code>SetParams</code> 更新页表指针。前者对捕获友好，后者依赖更新 API 对该节点类型的支持。MoE 路由若每步改变发出的专家核集合，拓扑变了，整步图通常要放弃，改成「静态满专家 + 掩码」或只捕获专家内部的 GEMM 小图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收益来自提交路径：参数就位、驱动校验、队列，从「每核一次」变成「每图一次」。GPU 上 MMA 与 HBM 流量不变。因此加速出现在 CPU 来不及喂 GPU 的短核序列上；已经融合成每层两三个大核、或 CPU 侧还有 Python 取样逻辑与图并行的路径上，加速会缩小。Graph 与 <a href="/llm/kernel-fusion-tiling">核融合</a> 是互补：融合减少节点数，图减少剩余节点的启动税；融合得足够狠时，图的边际收益下降，这是预期。</p><p>捕获得到的是当前上下文里的图，不能跨进程、跨 <code>cudaDevice</code> 共享。多卡张量并行时，每张卡各自捕获自己的那一截，NCCL 是否进图取决于该版本 NCCL 是否提供可捕获提交。进不了，则图只包计算，通信仍逐步 launch，中间仍可能出现 CPU 间隙。</p><p><span class="marginnote"><code>cudaGraphExecUpdate</code> 失败时必须整图重建。服务线程若在请求路径上同步重建，尾延迟会尖刺。应在空闲时为新桶预捕获，或把重建挪到后台流并在完成前走非图路径。</span></p><h3 id="与-pytorch-引擎的封装差异" tabindex="-1">与 PyTorch / 引擎的封装差异 <a class="header-anchor" href="#与-pytorch-引擎的封装差异" aria-label="Permalink to &quot;与 PyTorch / 引擎的封装差异&quot;">​</a></h3><p>PyTorch 的 <code>cudagraphs</code> 封装用 replay 时的静态地址约定，配合内存池；放松捕获模式仍不能让同步查询合法。TensorRT-LLM 更常在引擎构建期显式建图或捕获，形状范围写进引擎。vLLM 一类把 CUDA Graph 限在 decode 的固定 batch。封装不同，CUDA 合同相同：拓扑固定、捕获中无同步分配。调试应先关图跑数值，再开图比墙钟；图模式下的 CUDA 错误对应不到某一行 Python。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在默认流上捕获。不要为「所有 batch 都上图」建几十张从不命中的 exec。不要把取样、停用词、外部 tokenizer 塞进图。不要假设 Graph 能提高 Tensor Core 占用——它不改屋顶线。动态 batch 的正确姿势是：能 pad 的上图，不能 pad 的（变长 MoE 发出集、投机树深度变化）走逐步启动。</p><p>与 <a href="/llm/persistent-kernel">Persistent kernel</a> 相比：图减少的是 CPU 提交；持久核减少的是核与核之间的启动，并把流水线留在 SM 上。二者可以叠：图里 launch 一个持久核。叠之前先测是 CPU 受限还是 SM 在核间排水——弄错瓶颈会多维护一套捕获状态却看不见收益。</p><p><span class="marginnote">出处：CUDA Programming Guide 的 Graphs、stream capture 限制、<code>cudaGraphExecUpdate</code>；Runtime API。各推理引擎的分桶策略见其公开文档，本篇只保留与 CUDA 合同一致的部分，不把框架私有默认值写成规范。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推理用 CUDA Graph 重放拓扑稳定的 decode 步，削减短核启动税。</li><li>必须非默认流捕获；分配、同步、CPU 分支留在捕获外。</li><li>动态形状靠分桶 padding 或有限的参数更新；拓扑变化要重建或放弃整步图。</li><li>Prefill 与动态 MoE 常常不上整图；收益集中在 CPU 受限的 decode。</li><li>图不改变 HBM / MMA 屋顶线，也不替代融合与持久化核。</li><li>出处：CUDA Graphs 文档与 Runtime API；推理分桶是引擎层实践。</li></ul>',15))])}const D=o(s,[["render",u]]);export{B as __pageData,D as default};
